import { Router } from 'express';
import { prisma } from '../db/prisma.js';

// Best-effort backup of a receiving event (vendor or head-office) - mirrors what
// store/catalogStore.ts's receiveStock() already did to the browser's local copy. Without this,
// the batches table only ever moved on a sale (see routes/sales.ts) and never on the "in" side of
// stock, so it would drift from real on-hand qty just as badly, only in the opposite direction.
export const receivingRouter = Router();

interface ReceivingInput {
  // Generated by the frontend (catalogStore.receiveStock) for a genuinely new batch - reused here
  // rather than generating a separate id, so this DB's batch row and the browser's stay the same
  // row when a later sale/return backup needs to match it by id (see routes/sales.ts).
  batchId: string;
  itemId: string;
  itemNameAr: string;
  itemNameEn: string;
  barcode?: string;
  unit?: string;
  category?: string;
  basePrice?: number;
  vatRate?: number;
  requiresBatchTracking?: boolean;
  reorderLevel?: number;
  batchNo: string;
  expiryDate: string;
  receivedDate: string;
  qty: number;
  purchasePrice: number;
  purchaseDiscountPercent: number;
  costPrice: number;
}

receivingRouter.post('/', async (req, res) => {
  const body = req.body as ReceivingInput;
  try {
    // The item master isn't owned by receiving - never overwrite it on a repeat receive, only
    // create it the first time this DB has ever heard of this itemId (e.g. a local seed item or
    // a first-time ERP item that was never pushed here before).
    await prisma.item.upsert({
      where: { id: body.itemId },
      create: {
        id: body.itemId,
        barcode: body.barcode ?? body.itemId,
        nameAr: body.itemNameAr,
        nameEn: body.itemNameEn,
        unit: body.unit ?? '',
        category: body.category ?? '',
        basePrice: body.basePrice ?? 0,
        vatRate: body.vatRate ?? 0,
        requiresBatchTracking: body.requiresBatchTracking ?? true,
        reorderLevel: body.reorderLevel ?? 0,
      },
      update: {},
    });

    // Same "top up an existing batch number, else create a new row" rule catalogStore.receiveStock
    // uses locally, re-derived independently here rather than trusted from the client, since this
    // DB's own batches table may already differ from the browser's view of which batch is "new".
    const existing = await prisma.batch.findFirst({ where: { itemId: body.itemId, batchNo: body.batchNo } });
    if (existing) {
      await prisma.batch.update({ where: { id: existing.id }, data: { qtyOnHand: { increment: body.qty } } });
    } else {
      await prisma.batch.create({
        data: {
          id: body.batchId,
          itemId: body.itemId,
          batchNo: body.batchNo,
          expiryDate: new Date(body.expiryDate),
          receivedDate: new Date(body.receivedDate),
          qtyOnHand: body.qty,
          purchasePrice: body.purchasePrice,
          purchaseDiscountPercent: body.purchaseDiscountPercent,
          costPrice: body.costPrice,
        },
      });
    }
    res.status(201).json({ ok: true });
  } catch (err) {
    res.status(502).json({ error: String(err) });
  }
});
